mapper.select:
SELECT * FROM industry_concept 
WHERE industry_code = #{industryCode}

    AND concept_type = #{type}


    AND status = #{status}

ORDER BY usage_count DESC, created_at DESC

mapper.update:
UPDATE industry_concept 
SET status = #{status}, updated_at = NOW() 
WHERE id = #{id}

UPDATE industry_concept 
SET usage_count = usage_count + 1 
WHERE id = #{id}

mapper.select:
SELECT * FROM industry_learning_record 
WHERE industry_code = #{industryCode}
ORDER BY created_at DESC
